 function runSearch(entries,value,n,k,st,exact,mode,lang,interfaceLang){const keep=lastSearchQuery===value?selected?.id:null;results=search(entries,value,{norm:n,kind:k,status:st,literal:exact,mode,language:lang});suggestions=suggestQueries(value,results,{language:interfaceLang});searchPending=false;visible=30;selected=keep?results.find(r=>r.id===keep)||null:null;lastSearchQuery=value;activeSuggestion=-1;}
 function scheduleSearch(entries,value,n,k,st,exact,mode,lang,interfaceLang){clearTimeout(searchTimer);searchPending=!!value;searchTimer=setTimeout(()=>runSearch(entries,value,n,k,st,exact,mode,lang,interfaceLang),90);}
 function chooseSuggestion(value){query=value;suggestOpen=false;activeSuggestion=-1;submit();}
 function openResult(record){selected=record;if(searchMode==='words'&&record.matchedLanguages?.length&&!record.matchedLanguages.includes(language))language=record.matchLanguage;}
 function resultExcerpt(record){if(searchMode==='words'&&record.matchedLanguages?.length&&!record.matchedLanguages.includes(language))return record.matchLanguage==='pt'?record.matchExcerptPt:record.matchExcerptEs;return (view(record).integrated?view(record).text.slice(0,280):language==='pt'?record.matchExcerptPt:record.matchExcerptEs)||view(record).text.slice(0,280);}
 function queryKeys(event){
  if(event.key==='Escape'){suggestOpen=false;activeSuggestion=-1;return;}
  if(!suggestOpen||!suggestions.length||searchPending)return;
  if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();activeSuggestion=(activeSuggestion+(event.key==='ArrowDown'?1:-1)+suggestions.length)%suggestions.length;}
  else if(event.key==='Enter'&&activeSuggestion>=0){event.preventDefault();chooseSuggestion(suggestions[activeSuggestion]);}
 }
 onDestroy(()=>clearTimeout(searchTimer));
 $: relatives=selected&&corpus?related(selected,corpus):[];
 $: effects=selected&&corpus?effectsFor(selected,corpus):[];
 $: selectedConfirmations=selected&&corpus?confirmationsFor(selected,corpus):[];
 $: amendments=selected&&corpus?corpus.amendments.filter(a=>a.target===selected.id):[];
 onMount(async()=>{try{const res=await fetch(`${base}/corpus.json`);if(!res.ok)throw Error('Corpus unavailable');corpus=await res.json();index=createIndex(corpus);const params=new URLSearchParams(location.search);query=params.get('q')||'';norm=params.get('norm')||'';ui=params.get('ui')==='pt'?'pt':'es';language=params.get('lang')==='pt'?'pt':'es';integrated=params.get('integrated')==='1';searchMode=['expanded','precise','words'].includes(params.get('mode'))?params.get('mode'):'words';}catch(e){error=e.message;}});
 $: if(typeof document!=='undefined')document.documentElement.lang=ui;
 function consult(value){query=value;visible=30;selected=null;}
 function submit(){clearTimeout(searchTimer);runSearch(index,query,norm,kind,status,literal,searchMode,language,ui);suggestOpen=false;visible=30;selected=null;const url=new URL(location.href);for(const [key,value] of Object.entries({q:query,norm,ui,lang:language,integrated:integrated?'1':'0',mode:searchMode}))url.searchParams.set(key,value);history.replaceState(null,'',url);}
 function answer(){return makeAnswer(query,results,corpus,{language,integrated});}
 function download(){const url=URL.createObjectURL(new Blob([answer()],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`consulta-presbiteriana-${language}.md`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 async function copy(){try{await navigator.clipboard.writeText(answer());copyStatus=t('copied');}catch{copyStatus=t('copyError');}}
</script>
<svelte:head><title>Consulta Presbiteriana · PT / ES</title></svelte:head>
<div class="app">
