  <div class="intro"><p class="eyebrow">{t('eyebrow')}</p><h1>{t('h1')}<br/><span>{t('h2')}</span></h1><p class="lede">{t('lede')}</p></div>
  <div class="corpus-note"><strong>{t('unofficial')}</strong><span>{t('warning')}</span></div>
  <div class="filters language-controls"><label>{t('interface')}<select bind:value={ui}><option value="es">Español</option><option value="pt">Português</option></select></label><label>{t('reading')}<select bind:value={language}><option value="es">Español</option><option value="pt">Português</option></select></label><label class="checkbox"><input type="checkbox" bind:checked={integrated}/>{t('integrated')}</label></div>
  {#if error}<p role="alert" class="error">{error}</p>{/if}
  <form class="search" on:submit|preventDefault={submit}><label for="query">{t('question')}</label><div class="input-row"><input id="query" bind:value={query} placeholder={ui==='es'?'Membresía en iglesia local, bautismo de niños…':'Membros da igreja local, batismo de crianças…'} autocomplete="off" role="combobox" aria-autocomplete="list" aria-controls="query-suggestions" aria-expanded={!!query.trim()&&suggestOpen&&suggestions.length>0&&!searchPending} aria-activedescendant={activeSuggestion>=0?`query-suggestion-${activeSuggestion}`:undefined} on:input={()=>{suggestOpen=true;activeSuggestion=-1;}} on:focus={()=>suggestOpen=true} on:blur={()=>suggestOpen=false} on:keydown={queryKeys}/><button disabled={!corpus}>{t('consult')} →</button></div>{#if query.trim()&&suggestOpen&&suggestions.length&&!searchPending}<ul id="query-suggestions" class="suggestions" role="listbox" aria-label={ui==='pt'?'Sugestões de busca':'Sugerencias de búsqueda'}>{#each suggestions as suggestion,i}<li role="presentation"><button type="button" role="option" id={`query-suggestion-${i}`} aria-selected={activeSuggestion===i} class:active={activeSuggestion===i} on:mousedown|preventDefault on:click={()=>chooseSuggestion(suggestion)}><Highlight text={suggestion} {query}/></button></li>{/each}</ul>{/if}<p class="live-help">{ui==='pt'?'Os resultados aparecem enquanto você digita. Todas as palavras no mesmo artigo, nota ou decisão; frases juntas aparecem primeiro.':'Los resultados aparecen mientras escribís. Todas las palabras en el mismo artículo, nota o decisión; las frases juntas aparecen primero.'}</p></form>
  <div class="topics">{#each (ui==='es'?['membresía','actas','disciplina','diáconos','asamblea','recursos']:['membros','atas','disciplina','diáconos','assembleia','recursos']) as topic}<button on:click={()=>consult(topic)} class:active={query===topic}>{topic}</button>{/each}</div>
  <div class="filters"><label>{ui==='pt'?'Busca':'Búsqueda'}<select bind:value={searchMode}><option value="words">{ui==='pt'?'Todas as palavras':'Todas las palabras'}</option><option value="precise">{ui==='pt'?'Precisa por assunto':'Precisa por asunto'}</option><option value="expanded">{ui==='pt'?'Ampliada':'Ampliada'}</option></select></label><label>{t('norm')}<select bind:value={norm}><option value="">{t('all')}</option>{#each norms as n}<option value={n}>{n}</option>{/each}</select></label><label>{t('content')}<select bind:value={kind}><option value="">{t('everything')}</option><option value="articulo">{t('articles')}</option><option value="nota">{t('notes')}</option><option value="resolucion">{t('resolutions')}</option><option value="pagina">{t('supplement')}</option></select></label><label>{t('state')}<select bind:value={status}><option value="">{t('everything')}</option>{#each Object.keys(stateWords) as value}<option {value}>{stateLabel(value)}</option>{/each}</select></label><label class="checkbox"><input type="checkbox" bind:checked={literal}/>{searchMode==='words'?(ui==='pt'?'Palavras completas':'Palabras completas'):t('literal')}</label></div>
  {#if !corpus&&!error}<p role="status">{t('loading')}</p>{/if}
  {#if searchPending}<p role="status">{ui==='pt'?'Buscando…':'Buscando…'}</p>{/if}
  {#if query&&corpus&&!searchPending}
   <div class="result-bar"><p aria-live="polite"><strong>{results.length}</strong> {t('matches')}</p><div><button class="text-button" on:click={copy} disabled={!results.length||searchPending}>{t('copy')}</button><button class="text-button" on:click={download} disabled={!results.length||searchPending}>{t('download')} ↓</button></div></div>
   {#if copyStatus}<p role="status">{copyStatus}</p>{/if}<p class="search-help">{t('help')}</p>
   <div class="result-layout" class:with-detail={selected}><div class="results">
    {#each results.slice(0,visible) as r}<button class="result" class:selected={selected?.id===r.id} on:click={()=>openResult(r)}><span class="result-meta">{r.norm} · {r.id} · PDF {r.page}</span><span class="result-title"><Highlight text={label(r)} {query} prefixLast={!literal}/></span><span class="badge" class:changed={r.status==='modificado-2026'}>{stateLabel(r.status)}</span>{#if confirmationsFor(r,corpus).length}<span class="badge">{ui==='pt'?'Confirmação documental pendente':'Confirmación documental pendiente'}</span>{/if}<span class="excerpt"><Highlight text={resultExcerpt(r)} {query} prefixLast={!literal}/>…</span>{#if searchMode==='words'&&r.matchTier}<span class="match-tier">{r.matchTier==='phrase'?(ui==='pt'?'Palavras juntas':'Palabras juntas'):r.matchTier==='sentence'?(ui==='pt'?'Mesma oração':'Misma oración'):(ui==='pt'?'Mesmo artigo ou nota':'Mismo artículo o nota')}{#if r.matchLanguage!==language} · {r.matchLanguage==='pt'?'Português':'Español'}{/if}</span>{/if}<span class="terms">{view(r).pending?t('pending'):language==='pt'?t('pt'):view(r).comparativeReviewCompleteForUnit?t(r.source==='digesto'?'digestoReviewed':'reviewed'):r.translationStatus==='automatica-sin-revision'?t('automatic'):t('translated')}</span></button>{/each}
    {#if !results.length}<div class="empty"><h2>{t('none')}</h2><p>{t('retry')}</p></div>{/if}
    {#if visible<results.length}<button class="more" on:click={()=>visible+=30}>{t('more')} · {results.length-visible} {t('remaining')}</button>{/if}
   </div>
   {#if selected}<aside class="detail"><div class="detail-top"><span>{selected.id}</span><button aria-label={t('close')} on:click={()=>selected=null}>✕</button></div><h2><Highlight text={label(selected)} {query} prefixLast={!literal}/></h2><span class="badge">{stateLabel(selected.status)}</span><a class="source-link" href={`${base}/${selected.pdfUrl}`} target="_blank" rel="noreferrer">{t('pdf')} · {t('page')} {selected.page} ↗</a>
    {#each selectedConfirmations as item}<section class="scope" aria-label={ui==='pt'?'Confirmação documental pendente':'Confirmación documental pendiente'}><strong>{ui==='pt'?'Confirmação documental pendente':'Confirmación documental pendiente'} · {item.id}</strong><p>{language==='pt'?item.titlePt:item.titleEs}</p><p>{language==='pt'?item.findingPt:item.findingEs}</p><a href={`${base}/documentos/pendientes_confirmacion_documental_2026_${language}.md`} download>{ui==='pt'?'Baixar registro de pendências':'Descargar registro de pendientes'}</a></section>{/each}
    {#if selected.crossReferenceClassification}<p class="scope"><strong>{ui==='pt'?'Referência identificada':'Referencia identificada'}</strong>: {language==='pt'?selected.crossReferenceClassification.resolvedBodyPt:selected.crossReferenceClassification.resolvedBodyEs}. {language==='pt'?selected.crossReferenceClassification.findingPt:selected.crossReferenceClassification.findingEs}</p>{/if}
    {#if selected.crossHistoricalCompatibilityReview}<p class="scope"><strong>{ui==='pt'?'Cotejo transversal':'Cotejo transversal'}</strong>: {language==='pt'?selected.crossHistoricalCompatibilityReview.findingPt:selected.crossHistoricalCompatibilityReview.findingEs}</p>{/if}
    {#each selected.crossCompatibilityNoteIds||[] as nid}{@const review=corpus.records.find(n=>n.id===nid).crossHistoricalCompatibilityReview}<p class="scope"><strong>{nid}</strong>: {language==='pt'?review.findingPt:review.findingEs}</p>{/each}
    {#if selected.historicalCompatibilityReview}<p class="scope"><strong>{ui==='pt'?'Compatibilidade histórica':'Compatibilidad histórica'}</strong>: {language==='pt'?selected.historicalCompatibilityReview.findingPt:selected.historicalCompatibilityReview.findingEs}</p>{/if}
    {#if view(selected).pending}<p class="corpus-note">{t('pending')}</p>{/if}
    {#if view(selected).integrated}<h3>{t('integratedText')}</h3><p class="scope">{t('integrationWarning')}</p>{/if}
    {#if language==='es'&&view(selected).comparativeReviewCompleteForUnit}<p class="scope">{t(selected.source==='digesto'?'digestoReviewed':'reviewed')}</p>{/if}
    {#if language==='es'&&selected.translationStatus==='automatica-sin-revision'}<p class="scope">{t('automatic')}</p>{/if}<pre lang={view(selected).language}><Highlight text={view(selected).text} {query} prefixLast={!literal}/></pre>
    {#each amendments as a}<section class="amendment"><p class="eyebrow">{t('reform')} · EC {a.ec}</p><pre lang={language}><Highlight text={language==='pt'?a.textPt:a.textEs} {query} prefixLast={!literal}/></pre><p class="citation">{a.source} · PDF {a.pages.join(', ')}</p></section>{/each}
    {#if selected.integratedTextPt}<details><summary>{t('historic')}</summary><pre lang={language==='es'&&selected.textEs?'es':'pt'}><Highlight text={language==='es'&&selected.textEs?selected.textEs:selected.textOriginal} {query} prefixLast={!literal}/></pre></details>{/if}
    {#if language==='es'&&selected.textEs}<details><summary>{t('pt')}</summary><pre lang="pt"><Highlight text={selected.textOriginal} {query} prefixLast={!literal}/></pre></details>{/if}
    {#if relatives.length}<h3>{t('related')}</h3>{#each relatives as r}<details><summary>{label(r)}<span>{stateLabel(r.status)}</span></summary>{#each confirmationsFor(r,corpus) as item}<p class="scope"><strong>{ui==='pt'?'Confirmação documental pendente':'Confirmación documental pendiente'} · {item.id}</strong>: {language==='pt'?item.findingPt:item.findingEs}</p>{/each}{#if view(r).pending}<p class="scope">{t('pending')}</p>{/if}<pre lang={view(r).language}><Highlight text={view(r).text} {query} prefixLast={!literal}/></pre><a class="source-link" href={`${base}/${r.pdfUrl}`} target="_blank" rel="noreferrer">{t('pdf')} · {t('page')} {r.page} ↗</a></details>{/each}{/if}
   </aside>{/if}</div>
  {:else if corpus&&!query}<div class="start-grid"><section><p class="eyebrow">{t('corpus')}</p><h2>{t('pages')}</h2><p>{corpus.metadata.counts.articulo} {t('articles')} · {corpus.metadata.counts.nota} {t('notes')} · {corpus.metadata.counts.resolucion} {t('resolutions')}</p><p>{t('start')}</p></section><section><p class="eyebrow">{t('progress')}</p>{#each Object.entries(corpus.metadata.translationProgress||{}) as [name,progress]}<p><strong>{name==='manual'?'Manual':'Digesto'}</strong>: {progress.translated} / {progress.total} {t('units')}</p>{/each}{#if corpus.metadata.documentaryConfirmationProgress}<p><strong>{ui==='pt'?'Grupos de confirmação documental abertos':'Grupos de confirmación documental abiertos'}</strong>: {corpus.metadata.documentaryConfirmationProgress.openSelectedGroups} · {ui==='pt'?'separados do texto normativo':'separados del texto normativo'}</p>{/if}{#if corpus.metadata.normativeIntegrationProgress}<p><strong>{ui==='pt'?'Efeitos normativos examinados':'Efectos normativos examinados'}</strong>: {corpus.metadata.normativeIntegrationProgress.reviewedDecisions}/{corpus.metadata.normativeIntegrationProgress.totalDecisions} · {corpus.metadata.normativeIntegrationProgress.pendingDecisions} {t('remaining')}</p>{/if}{#if corpus.metadata.editorialConsolidationProgress}<p><strong>{ui==='pt'?'Suplemento consolidado':'Suplemento consolidado'}</strong>: {corpus.metadata.editorialConsolidationProgress.consolidatedDecisions}/398 · {ui==='pt'?'aprovação editorial definitiva pendente':'revisión editorial definitiva pendiente'}</p>{/if}{#if corpus.metadata.historicalCompatibilityProgress}<p><strong>{ui==='pt'?'Notas diretas conferidas':'Notas directas examinadas'}</strong>: {corpus.metadata.historicalCompatibilityProgress.comparedDirectNotes}/{corpus.metadata.historicalCompatibilityProgress.totalDirectNotes} · {ui==='pt'?'confirmações documentais pendentes':'confirmaciones documentales pendientes'}</p>{/if}{#if corpus.metadata.crossHistoricalCompatibilityProgress}<p><strong>{ui==='pt'?'Candidatas transversais classificadas':'Candidatas transversales clasificadas'}</strong>: {corpus.metadata.crossHistoricalCompatibilityProgress.reviewedCandidateNotes}/{corpus.metadata.crossHistoricalCompatibilityProgress.candidateNotes} · {corpus.metadata.crossHistoricalCompatibilityProgress.pendingCandidateNotes} {ui==='pt'?'candidatas pendentes de classificação':'candidatas pendientes de clasificación'}</p>{#if corpus.metadata.crossHistoricalCompatibilityProgress.candidateReviewComplete}<p>{ui==='pt'?'Classificação do rastreio concluída; confirmações documentais pendentes.':'Clasificación del rastreo concluida; confirmaciones documentales pendientes.'}</p>{/if}{/if}<p>{t('warning')}</p></section></div>{/if}
  <section class="downloads"><h2>{t('documents')}</h2><div>{#each documentNames as name}<a href={`${base}/documentos/${name}.md`} download>{name.replaceAll('_',' ')} · {['lista_trabajo_manual_presbiteriano','lista_trabalho_manual_presbiteriano_pt','revision_manual_2025_pt','estado_bilingue_es','estado_bilingue_pt'].includes(name)?t('documents'):name.startsWith('digesto_lote_')&&name.endsWith('_es_revisado')?t('digestoReviewed'):[ 'anexo_paginas_121_140_2025_es_revisado','anexo_paginas_101_120_2025_es_revisado','anexo_paginas_081_100_2025_es_revisado','anexo_paginas_061_080_2025_es_revisado','anexo_paginas_041_060_2025_es_revisado','anexo_paginas_021_040_2025_es_revisado','anexo_paginas_001_020_2025_es_revisado','sumario_indices_2025_es_revisado','preliminares_separadores_2025_es_revisado','reglamento_actas_2025_es_revisado','reglamento_junta_diaconal_2025_es_revisado','estatuto_iglesia_2025_es_revisado','reglamento_presbiterio_2025_es_revisado','estatuto_presbiterio_2025_es_revisado','reglamento_sinodo_2025_es_revisado','estatuto_sinodo_2025_es_revisado','reglamento_ce_2025_es_revisado','reglamento_sc_2025_es_revisado','constitucion_2025_es_revisada','codigo_disciplina_2025_es_revisado','principios_liturgia_2025_es_revisado','estatuto_ipb_2025_es_revisado'].includes(name)?t('reviewed'):name==='manual_2025_es'?t('translated'):name==='digesto_2026_es'?t('digestoReviewed'):name.includes('integrado')||name.startsWith('integracion_normativa_')?t('partialIntegration'):name.startsWith('pendientes_confirmacion_documental_')||name.startsWith('compatibilidad_transversal_')||name.startsWith('compatibilidad_notas_historicas_')||name.startsWith('suplemento_normativo_')||name.startsWith('revision_editorial_consolidacion_')?t('documents'):name.endsWith('_es')?t('partial'):t('complete')} ↓</a>{/each}</div></section>
 </main><footer>{t('footer')}</footer>
</div>
<style>
 .suggestions{list-style:none;margin:4px 0 0;padding:6px;background:#fffdf8;border:1px solid #bdc8bd;border-radius:8px;max-width:850px}.suggestions li{margin:0}.suggestions button{border:0;background:transparent;text-align:left;width:100%;padding:9px 14px;border-radius:4px;color:#243b35}.suggestions button:hover,.suggestions button.active{background:#e8eee3}.match-tier{display:block;font-size:11px;color:#496144;margin:5px 0}.live-help{font-size:12px;color:#627457;margin:8px 0 0}

.language-controls{margin-bottom:25px}

 :global(*){box-sizing:border-box} :global(body){margin:0;background:#f7f5ef;color:#243b35;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.55} :global(button),:global(input),:global(select){font:inherit} :global(button),:global(a){-webkit-tap-highlight-color:transparent} :global(button){cursor:pointer} :global(button:disabled){cursor:default;opacity:.55} :global(a){color:#214c43} :global(:focus-visible){outline:3px solid #b68c45;outline-offset:3px}
 .app{max-width:1440px;margin:auto}header{padding:28px 5%;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #dadfd6}.brand{text-decoration:none;font-weight:700;font-size:19px;display:flex;align-items:center;gap:12px}.book{background:#214c43;color:#fff9e9;padding:2px 9px;border-radius:7px;font-size:25px}.edition{font-size:12px;color:#6c7b73}main{padding:48px 5%}.intro{max-width:800px}.eyebrow{font-size:11px;letter-spacing:1.8px;font-weight:700;color:#677a6f}h1{font-family:Georgia,serif;font-size:clamp(38px,5vw,62px);font-weight:400;line-height:1.08;letter-spacing:-1.7px;margin:18px 0 24px}h1 span{color:#7b8778}.lede{font-size:17px;max-width:670px;color:#59695f}.corpus-note{display:flex;gap:18px;align-items:start;background:#eeece3;border:1px solid #dfdbca;border-radius:8px;padding:15px 18px;font-size:12px;margin:30px 0}.corpus-note strong{flex:0 0 170px;color:#6d623f}.corpus-note span{color:#6c705f}.search label{font-weight:600;display:block;margin-bottom:9px}.input-row{display:flex;gap:10px}.input-row input{flex:1;min-width:0;border:1px solid #bdc8bd;border-radius:8px;background:#fffdf8;padding:18px 20px;font-size:18px}.input-row button{background:#214c43;color:white;border:0;border-radius:8px;padding:12px 30px;font-weight:600}.topics{display:flex;flex-wrap:wrap;gap:9px;align-items:center;margin:15px 0 26px}.topics button{background:transparent;border:1px solid #d3d9ce;color:#51685c;border-radius:20px;padding:5px 13px;font-size:12px}.topics button:hover,.topics button.active{background:#e2e9df;border-color:#9cae9e}.filters{display:flex;gap:16px;flex-wrap:wrap;padding:17px 0;border-top:1px solid #dde0d5;border-bottom:1px solid #dde0d5}.filters label{font-size:12px;color:#69786d;display:flex;flex-direction:column;gap:5px}.filters select{border:1px solid #d2d9cc;padding:8px 9px;border-radius:5px;background:#fffdf8;max-width:255px;font-size:13px}.filters .checkbox{flex-direction:row;align-items:center;align-self:end;padding:9px}.result-bar{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:22px 0 4px}.result-bar p{font-size:14px}.result-bar strong{font-size:23px;margin-right:5px}.text-button{border:0;background:none;font-size:12px;padding:8px}.search-help{color:#798477;font-size:12px;max-width:800px;margin-bottom:24px}.result-layout{display:grid;grid-template-columns:1fr;gap:24px}.result-layout.with-detail{grid-template-columns:minmax(300px,1fr) minmax(360px,1.1fr)}.results{display:flex;flex-direction:column;gap:12px;min-width:0}.result{display:block;text-align:left;border:1px solid #e0e3d8;background:#fffdf8;padding:20px 23px;border-radius:8px;width:100%;color:#243b35}.result:hover,.result.selected{border-color:#799682;box-shadow:0 2px 12px #203c3210}.result-meta{display:block;font-size:10px;letter-spacing:1.2px;color:#798778}.result-title{display:block;font-family:Georgia,serif;font-size:20px;margin:7px 0 8px}.badge{display:inline-block;font-size:10px;border-radius:4px;background:#ecefe7;color:#697762;padding:4px 8px;line-height:1.4}.badge.changed{background:#deeadb;color:#375b3e}.excerpt{display:block;font-size:13px;color:#6a7568;margin:12px 0 9px;line-height:1.7}.terms{font-size:10px;color:#86907f}.detail{background:white;border:1px solid #dbe2d6;border-radius:10px;padding:25px;align-self:start;max-height:78vh;overflow:auto;position:sticky;top:20px;min-width:0}.detail-top{display:flex;justify-content:space-between;align-items:center;font-size:11px;color:#7c8779}.detail-top button{border:0;background:none;padding:8px}.detail h2{font-family:Georgia,serif;font-size:26px;font-weight:400;line-height:1.3}.detail h3{font-size:14px;margin-top:25px}pre{white-space:pre-wrap;font-family:Georgia,serif;font-size:15px;line-height:1.85;overflow-wrap:anywhere}.source-link{display:block;font-size:11px;margin:16px 0;text-decoration:underline}.amendment{background:#eff4e9;border-left:3px solid #799367;padding:16px;margin:20px -5px}.amendment p{font-size:12px}.amendment h3{margin-top:0}.scope,.citation{color:#627457}.detail details{padding:13px 0;border-top:1px solid #e3e6dc}.detail summary{cursor:pointer;font-weight:600;font-size:12px}.detail summary span{display:block;font-weight:400;font-size:10px;color:#809175;margin-top:4px}.more{background:#e8eee3;border:1px solid #c3d1ba;border-radius:5px;padding:14px;color:#496144}.empty{padding:28px;border:1px dashed #cbd4c5;border-radius:8px}.start-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin:36px 0}.start-grid section{background:#f0f1e8;border-radius:8px;padding:24px}.start-grid h2{font-family:Georgia,serif;font-weight:400;font-size:23px}.start-grid p:not(.eyebrow){font-size:13px;color:#71806e}.downloads{border-top:1px solid #d9dfd2;padding-top:26px;margin-top:40px}.downloads h2{font-size:13px}.downloads div{display:flex;gap:25px;flex-wrap:wrap}.downloads a{font-size:12px}footer{padding:25px 5%;border-top:1px solid #d9dfd2;color:#85907d;font-size:11px}.error{color:#963c2e}
 @media(max-width:900px){.result-layout.with-detail{grid-template-columns:1fr}.detail{position:static;max-height:none;grid-row:1}.corpus-note{flex-direction:column;gap:5px}.corpus-note strong{flex:auto}.start-grid{grid-template-columns:1fr}}@media(max-width:550px){header{padding:20px 5%;align-items:start}.brand{font-size:14px}.edition{font-size:10px;max-width:100px;text-align:right}main{padding-top:28px}.input-row button{padding:12px;font-size:13px}.input-row input{font-size:15px;padding:15px}.result-bar{align-items:start;flex-direction:column}.filters{gap:10px}.result{padding:17px}.detail{padding:18px}.downloads div{flex-direction:column;gap:12px}}
